-- Seed data for Cloudflare D1, generated from src/data/blues.ts (ARTISTS/PROFILES)
-- and scripts/seed-artists.ts (Lonnie Johnson showcase profile) — the only artist
-- data that exists in the project files. The full multi-language dataset (90+ artists,
-- reviews, concerts) lives only in the live Supabase database and was not available
-- to this migration — see the chat summary for how to export and import it separately.

INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'charley-patton', 'Charley Patton', 'Delta', '1891–1934', 'The father of the Delta blues — Dockery Plantation''s first star.', 0);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'blind-lemon-jefferson', 'Blind Lemon Jefferson', 'Delta', '1893–1929', 'The first male blues star to sell on record.', 1, 'September 1893, Coutchman, Texas — d. December 1929, Chicago', 'East Texas', '["The first commercially successful male country-blues recording artist. Paramount sold his records by the hundreds of thousands across the South in the late 1920s.","Self-accompanied on a busy, intricate, idiosyncratic guitar style. His repertoire — preserved on roughly 100 recorded sides between 1925 and 1929 — fed directly into Lead Belly, T-Bone Walker (who as a teenager led him around Dallas), and through them everyone since."]', 'Blues Hall of Fame (1980), Rock and Roll Hall of Fame (2022, Musical Excellence).', '["Black Snake Moan","Matchbox Blues","See That My Grave Is Kept Clean","Hangman''s Blues"]', '["Texas country-blues tradition"]', '["Paramount"]', '["Acoustic guitar","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'ma-rainey', 'Ma Rainey', 'Classic', '1886–1939', 'Mother of the Blues — the voice that took it to the cities.', 2, '26 April 1886, Columbus, Georgia — d. 22 December 1939', 'Georgia / TOBA vaudeville circuit', '["Gertrude \"Ma\" Rainey was on the road performing classic blues a decade before anyone bothered to record it. By the time she did record — for Paramount, starting 1923 — she had already earned the title Mother of the Blues.","She wrote much of her own material, ran her own touring company, owned theatres and was openly bisexual in songs like \"Prove It on Me Blues\" — extraordinary for the 1920s."]', 'Rock and Roll Hall of Fame (1990), Blues Hall of Fame (1983). August Wilson''s play and the 2020 Netflix film with Viola Davis and Chadwick Boseman brought her story to a new audience.', '["See See Rider Blues","Ma Rainey''s Black Bottom","Bo-Weavil Blues","Prove It on Me Blues"]', '["Travelling minstrel and tent-show tradition"]', '["Paramount"]', '["Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'bessie-smith', 'Bessie Smith', 'Classic', '1894–1937', 'The Empress of the Blues — vaudeville''s biggest star.', 3, '15 April 1894, Chattanooga, Tennessee — d. 26 September 1937, Clarksdale, Mississippi', 'Tennessee / TOBA vaudeville circuit', '["Mentored briefly by Ma Rainey on the Black vaudeville circuit, Bessie Smith became the highest-paid Black entertainer in 1920s America. Columbia signed her in 1923 and her debut, \"Downhearted Blues\", sold three-quarters of a million copies in six months.","She recorded with Louis Armstrong, James P. Johnson and a long list of jazz royalty. Her phrasing, dynamics and emotional authority are the foundation of nearly every female blues, jazz and soul singer who followed.","She died in a car accident in Clarksdale at 43. Janis Joplin paid for her unmarked grave to get a proper headstone in 1970."]', 'Grammy Hall of Fame, Rock and Roll Hall of Fame (1989, Early Influence). Direct line to Billie Holiday, Janis Joplin, Aretha Franklin and Etta James.', '["Downhearted Blues","St. Louis Blues","Nobody Knows You When You''re Down and Out","Backwater Blues"]', '["Ma Rainey"]', '["Columbia"]', '["Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'blind-willie-johnson', 'Blind Willie Johnson', 'Delta', '1897–1945', 'Sacred slide guitar that NASA sent into deep space.', 4);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'lead-belly', 'Lead Belly', 'Delta', '1888–1949', '12-string folk-blues that crossed every American border.', 5, 'January 1888, Mooringsport, Louisiana — d. 6 December 1949, New York', 'Louisiana / Texas', '["Huddie William Ledbetter was recorded by John and Alan Lomax in Louisiana''s Angola Prison in 1933. After his release he travelled north with the Lomaxes and became, against the racial grain of the 1930s, the centre of the New York folk-revival scene.","His twelve-string Stella, his enormous repertoire and his role as a bridge between the Delta and the Greenwich Village folk movement are the reason \"Goodnight, Irene\" was a #1 hit in 1950 and \"Rock Island Line\" launched the British skiffle craze that produced the Beatles."]', 'Rock and Roll Hall of Fame (1988, Early Influence). His repertoire is the connecting tissue between blues, country and modern American folk.', '["Goodnight, Irene","Where Did You Sleep Last Night","Cotton Fields","Midnight Special","Rock Island Line"]', '["Blind Lemon Jefferson (with whom he travelled in Texas)"]', '["ARC","Library of Congress","RCA Victor","Folkways"]', '["12-string Stella guitar","Accordion","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'son-house', 'Son House', 'Delta', '1902–1988', 'Raw, spiritual slide guitar — the preacher''s blues.', 6, '21 March 1902, Lyon, Mississippi — d. 19 October 1988, Detroit', 'Mississippi Delta', '["Eddie James House Jr. was a Baptist preacher who never fully made peace with playing the devil''s music — and that internal war is exactly what comes out of his records.","He recorded for Paramount in 1930, then for Alan Lomax in 1941–42, then disappeared. Rediscovered in Rochester, New York in 1964 by blues researchers, he returned to the stage and the folk-festival circuit and made some of the most spiritually intense recordings of the 1960s blues revival.","His unaccompanied a cappella performance of \"Grinnin'' in Your Face\" — just hand-claps and that thundering voice — is one of the great moments in American music."]', 'Direct teacher and mentor to Robert Johnson and Muddy Waters. Inducted into the Blues Hall of Fame (1980) and Rock and Roll Hall of Fame (2017, Early Influence).', '["Death Letter Blues","Grinnin'' in Your Face","Preachin'' the Blues","John the Revelator"]', '["Charley Patton","Willie Wilson"]', '["Paramount","Library of Congress","Columbia"]', '["National steel guitar (slide)","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'skip-james', 'Skip James', 'Delta', '1902–1969', 'Eerie falsetto and open D-minor tuning — the haunted blues.', 7);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'memphis-minnie', 'Memphis Minnie', 'Delta', '1897–1973', 'One of the first women to play the blues like she meant it.', 8);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'robert-johnson', 'Robert Johnson', 'Delta', '1911–1938', '29 recordings that defined the Delta blues forever.', 9, '8 May 1911, Hazlehurst, Mississippi — d. 16 August 1938, Greenwood, Mississippi (age 27)', 'Mississippi Delta', '["Robert Leroy Johnson cut just 29 songs across two short sessions — San Antonio in November 1936 and Dallas in June 1937 — and on the strength of those recordings became the most mythologised musician in American history.","His technique was unprecedented. Bass figures, melody and a percussive thumb-driven groove came out of a single acoustic guitar at once. Layered with that strained, haunted tenor and lyrics about restless travel, betrayal, the devil and the road, the records sound like nothing else cut in the 1930s.","The crossroads legend — that he sold his soul to play that well — was largely a later embellishment. What is documented: he learned in Hazlehurst from the older bluesman Ike Zimmerman, returned to the Delta a transformed player, and died young under disputed circumstances in 1938."]', 'Columbia''s 1961 King of the Delta Blues Singers compilation landed in the hands of the British blues generation and changed rock music. Clapton, the Stones, Led Zeppelin and Bob Dylan all owe him directly. Inducted into the Rock and Roll Hall of Fame as Early Influence in 1986.', '["Cross Road Blues","Sweet Home Chicago","Hellhound on My Trail","Love in Vain","Come On in My Kitchen"]', '["Son House","Charley Patton","Lonnie Johnson","Kokomo Arnold"]', '["Vocalion","ARC","Columbia (posthumous)"]', '["Acoustic guitar","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'big-bill-broonzy', 'Big Bill Broonzy', 'Chicago', '1903–1958', 'From Mississippi sharecropper to first ambassador of the blues in Europe.', 10);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 't-bone-walker', 'T-Bone Walker', 'Texas', '1910–1975', 'Invented the electric blues guitar solo. Period.', 11, '28 May 1910, Linden, Texas — d. 16 March 1975', 'Dallas, Texas', '["Aaron Thibeaux Walker was the first electric blues guitar hero — single-string solos, jazz chord voicings, swing rhythm section, the guitar held flat like a steel — and his 1947 \"Stormy Monday\" is one of the most-covered songs in popular music.","He led B.B. King away from the cotton fields. He showed Chuck Berry the duck-walk (almost literally). The entire post-war electric blues style starts with him."]', 'Blues Hall of Fame (1980), Rock and Roll Hall of Fame (1987, Early Influence).', '["Call It Stormy Monday","T-Bone Shuffle","Mean Old World"]', '["Blind Lemon Jefferson (whom he led as a boy)","Lonnie Johnson","Charlie Christian"]', '["Capitol","Black & White","Imperial","Atlantic"]', '["Hollow-body electric guitar","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'lightnin-hopkins', 'Lightnin'' Hopkins', 'Texas', '1912–1982', 'Houston''s poet of the boogie — over 80 albums.', 12);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'john-lee-hooker', 'John Lee Hooker', 'Delta', '1917–2001', 'Hypnotic boogie and a foot that never stopped tapping.', 13, '22 August 1917 (disputed), Coahoma County, Mississippi — d. 21 June 2001, California', 'Mississippi → Detroit', '["Hooker moved to Detroit in the 1940s to work in the auto plants and became the city''s blues. \"Boogie Chillen''\" (1948) went to #1 R&B and sold a million copies on the strength of one chord, a foot-stomp and that conspiratorial spoken-sung voice.","He played his own time — not 12-bar, not 16-bar, but however long the groove needed to be — and recorded for so many labels under so many pseudonyms that nobody has ever counted his sessions.","His 1989 album The Healer, with Carlos Santana, Bonnie Raitt and Robert Cray, reintroduced him to a new generation and won a Grammy."]', 'Four Grammy Awards, induction into the Rock and Roll Hall of Fame (1991).', '["Boogie Chillen''","Boom Boom","One Bourbon, One Scotch, One Beer","I''m in the Mood"]', '["Tony Hollins","Charley Patton"]', '["Modern","Vee-Jay","Chess","Silvertone"]', '["Electric guitar","Voice","Foot-stomp"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'muddy-waters', 'Muddy Waters', 'Chicago', '1913–1983', 'The man who took the Delta to Chicago and plugged it in.', 14, '4 April 1913, Issaquena County, Mississippi — d. 30 April 1983, Westmont, Illinois (age 70)', 'Stovall Plantation, Mississippi → Chicago', '["McKinley Morganfield was first recorded in 1941 by Alan Lomax for the Library of Congress while he was driving a tractor on Stovall Plantation outside Clarksdale. Hearing himself on playback decided his future.","In 1943 he boarded the train to Chicago and within a few years had plugged the Delta slide guitar into an amplifier. With Little Walter on harmonica, Otis Spann on piano, Willie Dixon on bass and a series of fearsome drummers, his Chess Records band created the template for electric blues — and, through it, rock and roll.","His 1958 British tour, played at full volume with a Telecaster, scandalised the folk-purist audience but lit the fuse on the British blues boom. The Rolling Stones named themselves after his 1950 single."]', 'Six Grammys, a 1987 Rock and Roll Hall of Fame induction, and a direct line of descent that runs through every blues-rock band of the last sixty years.', '["Hoochie Coochie Man","Mannish Boy","Got My Mojo Working","Rollin'' Stone","I''m Ready"]', '["Son House","Robert Johnson","Big Bill Broonzy"]', '["Aristocrat","Chess","Blue Sky"]', '["Electric guitar (slide)","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'howlin-wolf', 'Howlin'' Wolf', 'Chicago', '1910–1976', '300-pound voice that shook the walls of Chess Records.', 15, '10 June 1910, White Station, Mississippi — d. 10 January 1976, Hines, Illinois', 'Mississippi Delta → Memphis → Chicago', '["Chester Arthur Burnett was 6''3\", weighed close to 300 pounds, and had a voice that sounded like gravel being shovelled. He was first recorded by Sam Phillips at Sun Studio in Memphis before moving to Chicago in 1953 to record exclusively for Chess.","His band — at various times including Hubert Sumlin on guitar — produced some of the most aggressive, primal sides in the Chess catalogue. Where Muddy was suave and confident, Wolf was elemental and unsettling.","Cream covered \"Spoonful\". Led Zeppelin covered \"Killing Floor\" (as \"The Lemon Song\"). The Doors covered \"Back Door Man\". The Stones cut \"Little Red Rooster\"."]', 'Inducted into the Rock and Roll Hall of Fame (1991) and Blues Hall of Fame (1980).', '["Smokestack Lightnin''","Spoonful","Killing Floor","Back Door Man","Little Red Rooster"]', '["Charley Patton","Sonny Boy Williamson II"]', '["RPM","Chess"]', '["Voice","Acoustic & electric guitar","Harmonica"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'elmore-james', 'Elmore James', 'Chicago', '1918–1963', 'King of the slide — the riff every blues-rock guitarist stole.', 16);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'willie-dixon', 'Willie Dixon', 'Chicago', '1915–1992', 'Bassist, producer and songwriter behind half of Chess.', 17, '1 July 1915, Vicksburg, Mississippi — d. 29 January 1992', 'Mississippi → Chicago', '["If Muddy and Wolf were the faces of Chess Records, Willie Dixon was its engine. As staff songwriter, producer, arranger and house bassist he wrote or co-wrote nearly every blues standard you can name from the 1950s.","He famously had to sue Led Zeppelin twice to be credited (and paid) for songs they had simply taken — \"Whole Lotta Love\" / \"You Need Love\" and \"Bring It On Home\" — and used the settlements to fund the Blues Heaven Foundation, dedicated to helping older blues artists recover their publishing rights."]', 'Grammy winner, Blues Hall of Fame (1980), Rock and Roll Hall of Fame (1994).', '["Hoochie Coochie Man","I Just Want to Make Love to You","Little Red Rooster","Spoonful","Back Door Man","You Shook Me"]', '["Big Bill Broonzy","Memphis Slim"]', '["Chess (staff)","Cobra","Bluesville"]', '["Upright bass","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'little-walter', 'Little Walter', 'Chicago', '1930–1968', 'Plugged the harmonica into an amp and never looked back.', 18);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'jimmy-reed', 'Jimmy Reed', 'Chicago', '1925–1976', 'The lazy shuffle that the Stones, Elvis and everyone else copied.', 19);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'bb-king', 'B.B. King', 'Classic', '1925–2015', 'Lucille, vibrato and a smile that conquered the world.', 20, '16 September 1925, Itta Bena, Mississippi — d. 14 May 2015, Las Vegas (age 89)', 'Mississippi Delta → Memphis', '["Riley B. King left a Mississippi plantation, joined his cousin Bukka White in Memphis, and became a DJ on WDIA where his on-air name — Beale Street Blues Boy — got shortened to B.B.","He never strummed chords behind his solos: he sang the lyrics, then made Lucille sing the answer. That call-and-response between voice and a single-string vibrato lick became the most-copied vocabulary in electric blues.","Over a sixty-year touring career he played a documented 15,000+ concerts, an output unrivalled in popular music."]', '15 Grammy Awards, a Presidential Medal of Freedom (2006), and a Memphis museum on Beale Street. "The Thrill Is Gone" (1969) brought the blues into mainstream American radio.', '["The Thrill Is Gone","Every Day I Have the Blues","Sweet Little Angel","Rock Me Baby"]', '["T-Bone Walker","Lonnie Johnson","Django Reinhardt","Charlie Christian"]', '["RPM","Kent","ABC-Paramount","MCA"]', '["Gibson ES-355 \"Lucille\"","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'albert-king', 'Albert King', 'Texas', '1923–1992', 'Upside-down Flying V and the bending hand SRV worshipped.', 21);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'freddie-king', 'Freddie King', 'Texas', '1934–1976', 'Texas-Chicago hybrid — "Hide Away" is on every guitarist''s playlist.', 22);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'otis-rush', 'Otis Rush', 'Chicago', '1934–2018', 'West Side soul-blues — left-handed, upside-down, devastating.', 23);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'magic-sam', 'Magic Sam', 'Chicago', '1937–1969', 'The Hendrix of the West Side, gone at 32.', 24);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'junior-wells', 'Junior Wells', 'Chicago', '1934–1998', 'Sharp-suited harmonica master and Buddy Guy''s lifelong partner.', 25);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'koko-taylor', 'Koko Taylor', 'Chicago', '1928–2009', 'Queen of the Blues — "Wang Dang Doodle" still rattles the rafters.', 26);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'etta-james', 'Etta James', 'Classic', '1938–2012', 'From doo-wop to deep blues — "At Last" is just the start.', 27, '25 January 1938, Los Angeles — d. 20 January 2012', 'Los Angeles / Chess Records Chicago', '["Jamesetta Hawkins started as a teenage R&B doo-wop singer, signed to Chess at 22, and over the next forty years moved fluidly between blues, soul, gospel, jazz and rock without losing the gravity in her voice for a second.","Her version of \"At Last\" — recorded in 1960 with strings — became one of the best-known American recordings of any genre."]', 'Six Grammy Awards, Rock and Roll Hall of Fame (1993), Blues Hall of Fame (2001).', '["At Last","I''d Rather Go Blind","Tell Mama","Something''s Got a Hold on Me"]', '["Billie Holiday","Dinah Washington"]', '["Modern","Chess / Argo","Island"]', '["Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'buddy-guy', 'Buddy Guy', 'Chicago', '1936–', 'The bridge from Muddy to Hendrix — and still on stage.', 28, '30 July 1936, Lettsworth, Louisiana — still active', 'Louisiana → Chicago', '["Buddy Guy arrived in Chicago in 1957 with a guitar he had built out of two paint cans and a piece of wood. By 1960 he was Chess Records'' house guitarist, playing on records by Wolf, Muddy and Sonny Boy Williamson II.","His wild, volume-on-eleven, flamboyantly theatrical style was too much for Leonard Chess in the studio, but Hendrix, Clapton, Beck and Stevie Ray Vaughan all worshipped him — and finally, on his 1991 comeback Damn Right, I''ve Got the Blues, the rest of the world caught up."]', 'Eight Grammys, Kennedy Center Honors (2012), Presidential Medal of Freedom recipient. Owner of the Legends club in Chicago — the most important room in the city.', '["Stone Crazy","First Time I Met the Blues","Damn Right, I''ve Got the Blues","Mustang Sally"]', '["Guitar Slim","B.B. King","T-Bone Walker"]', '["Chess","Vanguard","Silvertone","RCA / Jive"]', '["Polka-dot Stratocaster","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'eric-clapton', 'Eric Clapton', 'British', '1945–', 'Cream, Bluesbreakers, Derek — the British invasion of the blues.', 29, '30 March 1945, Ripley, Surrey, England', 'England — British blues boom', '["Through the Yardbirds, John Mayall''s Bluesbreakers, Cream and Derek and the Dominos, Clapton turned the British blues obsession with Chess Records and Robert Johnson into stadium rock.","Whatever you think of the long solo career that followed, his run from 1965''s Bluesbreakers with Eric Clapton through 1970''s Layla is one of the great six-year stretches in electric blues guitar."]', 'Inducted into the Rock and Roll Hall of Fame three times. Crossroads Centre Antigua, the addiction-treatment foundation he set up, is funded largely by his recurring Crossroads Guitar Festival.', '["Crossroads (Cream)","Layla (Derek & the Dominos)","Have You Ever Loved a Woman","Five Long Years"]', '["Robert Johnson","Freddie King","B.B. King","Buddy Guy"]', '["Decca","Polydor","RSO","Reprise"]', '["Electric guitar","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'stevie-ray-vaughan', 'Stevie Ray Vaughan', 'Texas', '1954–1990', 'Texas tone, hummingbird right hand, gone far too soon.', 30, '3 October 1954, Dallas, Texas — d. 27 August 1990, East Troy, Wisconsin', 'Texas', '["Younger brother of Jimmie Vaughan, Stevie soaked up Albert King, Otis Rush, Hendrix and Lonnie Mack and welded them together with a tone and attack so physical it sounded like the strings hurt him.","His 1983 debut Texas Flood single-handedly proved there was still an audience for hard, traditional electric blues. Six years and four studio albums later he was clean, sober, playing better than ever, and killed in a helicopter crash leaving an Eric Clapton show in Wisconsin."]', 'Six Grammys (four posthumous), Rock and Roll Hall of Fame (2015), the standard against which every modern blues-rock guitarist is still measured.', '["Texas Flood","Pride and Joy","Cold Shot","Tightrope","Crossfire"]', '["Albert King","Jimi Hendrix","Lonnie Mack","Buddy Guy"]', '["Epic"]', '["Fender Stratocaster (\"Number One\")","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'joe-bonamassa', 'Joe Bonamassa', 'Modern', '1977–', 'Independent blues-rock empire — vintage tone and a relentless tour bus.', 31);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order) VALUES (lower(hex(randomblob(16))), 'shemekia-copeland', 'Shemekia Copeland', 'Modern', '1979–', 'Johnny''s daughter, the new queen of blues with a political voice.', 32);
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'samantha-fish', 'Samantha Fish', 'Modern', '1989–', 'Kansas City fire — cigar-box slide and rock-blues hooks.', 33, '30 January 1989, Kansas City, Missouri', 'Kansas City', '["A drummer first, Samantha Fish picked up the guitar in her teens, was discovered at the King Biscuit Festival in Arkansas, and signed to Ruf Records in 2011. Six albums later she had moved decisively from straight blues into a brassy, hook-driven blues-rock with cigar-box slide solos.","Her 2023 collaboration with Jesse Dayton, Death Wish Blues, hit #1 on the Billboard Blues chart."]', 'Three Blues Music Awards, the leading commercial face of the new generation of women in blues.', '["Bulletproof","Chills & Fever","Bitch on the Run","Faster"]', '["Tom Petty","Stevie Ray Vaughan","Junior Kimbrough","Bonnie Raitt"]', '["Ruf","Rounder","Round Hill"]', '["Electric guitar (incl. cigar-box)","Voice"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'larkin-poe', 'Larkin Poe', 'Modern', '2010–', 'Lovell sisters — roots-rock, lap-steel and tight harmonies.', 34, 'Megan Lovell 1989, Rebecca Lovell 1991 — Atlanta, Georgia', 'Atlanta, Georgia', '["Sisters Rebecca and Megan Lovell started as part of the bluegrass trio The Lovell Sisters, then formed Larkin Poe (named for a great-great-great-grandfather) in 2010. Six studio albums, a Grammy nomination, and a YouTube channel of impeccable blues covers later, they are the most visible roots-rock duo of their generation."]', 'Grammy-nominated for Best Contemporary Blues Album (2020, Self Made Man) and (2022, Paint the Roses).', '["Preachin'' Blues","Bleach Blonde Bottle Blues","Strike Gold","She''s a Self-Made Man"]', '["Allman Brothers","Son House","Skip James","Mississippi Fred McDowell"]', '["RH Music","Tricki-Woo"]', '["Lap-steel guitar (Megan)","Electric guitar & voice (Rebecca)"]');
INSERT INTO artists (id, slug, name, tag, era, short, sort_order, born, origin, bio, legacy, signature_songs, influences, labels, instruments_simple) VALUES (lower(hex(randomblob(16))), 'christone-kingfish-ingram', 'Christone "Kingfish" Ingram', 'Modern', '1999–', 'Clarksdale-born phenom keeping the Delta line unbroken.', 35, '19 January 1999, Clarksdale, Mississippi', 'Clarksdale, Mississippi — the same town that produced Muddy Waters and John Lee Hooker', '["Trained at the Delta Blues Museum''s after-school programme in Clarksdale, Christone \"Kingfish\" Ingram released his debut Kingfish on Alligator at 20 and won a Grammy for Best Contemporary Blues Album three years later.","Critics from Buddy Guy to Vernon Reid have called him the most important young blues artist to appear in a generation — the proof that the line from Charley Patton to today has never broken."]', 'Grammy winner (2022), three Blues Music Awards, on the cover of Living Blues at 20.', '["Outside of This Town","662","Empty Promises","Long Distance Woman"]', '["Buddy Guy","B.B. King","Albert King","Prince"]', '["Alligator"]', '["Electric guitar","Voice"]');
INSERT INTO artists (id, slug, name, alt_name, tag, era, short, born, died, origin, active_years, bio, legacy, signature_songs, influences, labels, instruments_simple, family, formative, instruments, anecdotes, collaborators, videos, discography, awards, related_slugs, sort_order) VALUES (lower(hex(randomblob(16))), 'lonnie-johnson', 'Lonnie Johnson', 'Alonzo Johnson', 'Classic', '1899–1970', 'Jazz-blues-pioner som oppfant gitarsoloen og påvirket alle som fulgte.', '8. februar 1899', '16. juni 1970', 'New Orleans, Louisiana (bodde i Toronto fra 1960-tallet)', '1920s–1970', '["Lonnie Johnson var en av de mest innflytelsesrike og nyskapende gitaristene i amerikansk musikkhistorie, en sann pioner som bygde bro mellom blues, jazz og tidlig rhythm & blues. Født i New Orleans i 1899 vokste han opp i en stor musikalsk familie og lærte seg flere instrumenter.","Etter å ha vunnet en talentkonkurranse på Booker T. Washington Theatre i 1925, signerte han med OKeh Records og begynte en produktiv innspillingskarriere som strakte seg over fire tiår. Johnsons revolusjonerende enkeltstreng-gitarsoloer kom før den elektriske gitarens tidsalder og påvirket direkte B.B. King, T-Bone Walker, Robert Johnson og Django Reinhardt.","Han spilte inn duetter med Louis Armstrong, Duke Ellington og Eddie Lang – banebrytende tverr-rasielle samarbeid på 1920-tallet. Hiten ''Tomorrow Night'' fra 1948 nådde førsteplass på R&B-listene og solgte over tre millioner eksemplarer. Etter år i mørke der han jobbet som hotelljobber i Philadelphia, ble han gjenoppdaget i 1960 og flyttet til Toronto, Canada, hvor han tilbrakte sitt siste tiår med å opptre på folkfestivaler og klubber, og ble et adoptert ikon for den kanadiske bluesscenen."]', 'Lonnie Johnson regnes allment som faren til gitarsoloen i populærmusikk. Hans enkeltstreng-teknikk påvirket direkte B.B. King, T-Bone Walker, Robert Johnson, Django Reinhardt og praktisk talt alle blues- og jazzgitarister som fulgte. B.B. King kalte ham ''den mest innflytelsesrike gitaristen i blueshistorien.''', '["Tomorrow Night","Mr. Johnson''s Blues","Playing with the Strings","Got the Blues for Murder Only"]', '["New Orleans-tradisjon","Eddie Lang","Louis Armstrong"]', '["OKeh","King","Prestige/Bluesville","Columbia"]', '["Akustisk gitar","Elektrisk gitar","Fiolin","Vokal"]', '[{"relation":"Far","name":"James Johnson","note":"Musiker; familien var stor og musikalsk"},{"relation":"Bror","name":"James ''Steady Roll'' Johnson","note":"Også bluesmusiker; mange søsken spilte musikk"},{"relation":"Kone","name":"Mary Williams Johnson","note":"Gift på 1920-tallet"}]', '["Vokste opp i en stor musikalsk familie i New Orleans der praktisk talt alle spilte instrumenter; lærte fiolin, gitar, piano og mandolin som barn.","Mistet det meste av familien i influensapandemien i 1918, et ødeleggende slag som formet hans emosjonelle dybde som artist.","Vant et to-ukers engasjement på Booker T. Washington Theatre i en bluestalentkonkurranse i 1925, som lanserte innspillingskarrieren hans hos OKeh Records.","Hans banebrytende duetter med hvite gitaristen Eddie Lang (1928–1929) var noen av de første tverr-rasielle innspillingssamarbeidene i amerikansk musikkhistorie.","Etter år i mørke der han jobbet som hotelljobber i Philadelphia, ble han gjenoppdaget av platesamleren Chris Albertson i 1960 og lanserte et comeback."]', '[{"category":"Gitar","name":"Various acoustic guitars","years":"1920s–1970","note":"Pioner innen enkeltstreng-gitarsoloer; hans rene, presise plukketeknikk var revolusjonerende for tiden."},{"category":"Gitar","name":"Various hollow-body electrics","years":"1940s–1970","note":"Gikk smidig over til elektrisk gitar, og beholdt sin signatur rene tone."},{"category":"Annet","name":"Violin","years":"1910s–1920s","note":"Opprinnelig trent på fiolin; opptrådte av og til med det gjennom karrieren."},{"category":"Vokal","name":"Vocals","years":"1920s–1970","note":"Glatt, urban vokalstil som påvirket generasjoner av blues- og R&B-sangere."}]', '["Johnsons gitarduetter med Eddie Lang i 1928–1929 (kreditert som ''Blind Willie Dunn'' for å skjule hans italienske opphav) var blant de første tverr-rasielle innspillingssesjonene i amerikansk musikk – en dristig handling under Jim Crow-æraen.","B.B. King sa en gang: ''Lonnie Johnson var den første gitaristen jeg hørte som spilte soloer med enkelttoner. Han viste meg at en gitar kunne synge som en menneskestemme. Uten ham ville det ikke vært noen B.B. King.''","Da Johnson ble gjenoppdaget i 1960, jobbet han som vaktmester på Benjamin Franklin Hotel i Philadelphia. Han hadde ikke opptrådt offentlig på nesten et tiår.","Etter å ha flyttet til Toronto tidlig på 1960-tallet, ble Johnson en elsket skikkelse i den kanadiske folk- og bluesscenen, og opptrådte på klubber som Penny Farthing og inspirerte en generasjon kanadiske bluesmusikere.","Robert Johnson (ingen slektning) studerte visstnok Lonnie Johnsons plater besatt. De to Johnson''ene, ubeslektede men forbundet gjennom bluesen, representerer tvillingpilarene i akustisk og elektrisk blues-gitarinnovasjon."]', '[{"name":"Louis Armstrong","years":"1927–1929","note":"Spilte inn banebrytende duetter inkludert ''Hotter Than That''"},{"name":"Duke Ellington","years":"1927–1928","note":"Sesjonsgitarist på flere Ellington-innspillinger"},{"name":"Eddie Lang","years":"1928–1929","note":"Gitarduetter; banebrytende tverr-rasielt samarbeid"},{"name":"Victoria Spivey","years":"1960s","note":"Gjenforeningsinnspillinger på Spivey Records under comebacket"},{"name":"Elmer Snowden","years":"1960s","note":"Opptrådte sammen på folkemusikkfestivaler i Toronto"}]', '[{"kind":"featured","title":"Lonnie Johnson – Blues By Lonnie Johnson (Full Album)","youtube_id":"MhqYz0DXG-Y","channel":"All That Jazz Don Kaart","note":"Guitar, Vocals – Lonnie Johnson · Piano – Claude Hopkins · Tenor Saxophone – Hal Singer · Bass – Wendell Marshall."},{"kind":"more","title":"Lonnie Johnson - Swingin'' The Blues - 1966","youtube_id":"8DCdN0xPnLg","channel":"lupine22","duration":"3:15","views":"213.8K views"},{"kind":"more","title":"Lonnie Johnson Too Late To Cry","youtube_id":"uVjGE-r7lDk","channel":"pitotas30","duration":"5:08","views":"482.8K views"},{"kind":"more","title":"Blues Chronicles #15: Lonnie Johnson – Guitar History Lesson – Reverend Robert Jones","youtube_id":"j2eN_pXgU3w","channel":"TrueFire","duration":"4:01","views":"6.4K views"},{"kind":"more","title":"Blues for Lonnie Johnson – Robben Ford, Guildford 29/05/24","youtube_id":"pXYg2j_F0CY","channel":"Paddy Blight","duration":"4:36","views":"29.1K views"}]', '[{"year":1925,"title":"Mr. Johnson''s Blues","producer":"Ralph Peer","label":"OKeh Records","musicians_count":1,"notes":"En av hans tidligste innspillinger etter å ha vunnet talentkonkurransen; Ralph Peer ledet OKeh race records-sesjonene"},{"year":1927,"title":"Hotter Than That (with Louis Armstrong)","producer":"Tommy Rockwell","label":"OKeh Records","musicians_count":3,"notes":"Historisk samarbeid med Louis Armstrong and His Hot Five; Tommy Rockwell ledet"},{"year":1928,"title":"Guitar Blues / Blue Guitars (with Eddie Lang)","producer":"Tommy Rockwell","label":"OKeh Records","musicians_count":1,"notes":"Banebrytende tverr-rasiell gitarduett; Lang kreditert som ''Blind Willie Dunn'' for å skjule hans italienske opphav"},{"year":1928,"title":"Playing with the Strings","producer":"Tommy Rockwell","label":"OKeh Records","musicians_count":1,"notes":"Viser hans revolusjonerende enkeltstreng-soloteknikk; regnes som fødselen av gitarsoloen i populærmusikk"},{"year":1948,"title":"Tomorrow Night","producer":"Henry Glover","label":"King Records","musicians_count":1,"chart":"#1 R&B","sales":"3,000,000+","notes":"#1 R&B-hit; solgte over 3 millioner eksemplarer; Henry Glover produserte ved Kings Cincinnati-studio"},{"year":1960,"title":"Blues by Lonnie Johnson","producer":"Chris Albertson","label":"Prestige/Bluesville","musicians_count":2,"notes":"Comebackalbum etter gjenoppdagelsen av Chris Albertson; innspilt ved Rudy Van Gelders legendariske studio"},{"year":1963,"title":"Lonnie Johnson with Elmer Snowden","producer":"Kenneth S. Goldstein","label":"Prestige/Bluesville","musicians_count":1,"notes":"Duetter med banjolegenden Elmer Snowden; Kenneth S. Goldstein produserte for Prestige"},{"year":1967,"title":"Stompin'' at the Penny","producer":"John Hammond","label":"Columbia (Canada)","musicians_count":1,"notes":"Liveinnspilling på Torontos Penny Farthing-kaffebar; produsert av den legendariske John Hammond for Columbia"}]', '[{"year":1970,"title":"Blues Hall of Fame (innlemmet posthumt 1990)","category":"Pioner / Utøver"},{"year":2007,"title":"Grammy Hall of Fame","category":"''Playing with the Strings'' innlemmet"}]', '["bb-king","t-bone-walker","robert-johnson","blind-lemon-jefferson"]', 999);

-- Added: King Biscuit Boy, Sue Foley, Colin James (Voices from the Delta homepage section)
INSERT INTO artists (id, slug, name, tag, era, active_years, img, country, sort_order, short_no, short_en, short_sv, short_de, short_pl) VALUES (lower(hex(randomblob(16))), 'king-biscuit-boy', 'King Biscuit Boy', 'Modern', '1961–2003', '1961–2003', 'https://upload.wikimedia.org/wikipedia/commons/f/ff/KBB.gif', 'Canada', 900, 'King Biscuit Boy, født Richard Alfred Newell i Hamilton, Ontario, var en av Canadas mest kjøpte og innflytelsesrike munnspillere, kjent for sin råe Chicago-inspirerte stil.', 'King Biscuit Boy, born Richard Alfred Newell in Hamilton, Ontario, was one of Canada''s most celebrated and influential harmonica players, known for his raw Chicago-inspired style.', 'King Biscuit Boy, född Richard Alfred Newell i Hamilton, Ontario, var en av Kanadas mest hyllade och inflytelserika munspelare, känd för sin råa Chicago-inspirerade stil.', 'King Biscuit Boy, geboren als Richard Alfred Newell in Hamilton, Ontario, war einer der bekanntesten kanadischen Mundharmonikaspieler mit einem rohen, von Chicago inspirierten Stil.', 'King Biscuit Boy, urodzony jako Richard Alfred Newell w Hamilton w Ontario, był jednym z najbardziej cenionych kanadyjskich harmonijkarzy, znanym z surowego stylu inspirowanego Chicago.');
INSERT INTO artists (id, slug, name, tag, era, active_years, img, country, sort_order, short_no, short_en, short_sv, short_de, short_pl) VALUES (lower(hex(randomblob(16))), 'sue-foley', 'Sue Foley', 'Modern', '1988–present', '1988–present', 'https://upload.wikimedia.org/wikipedia/commons/a/a2/Sue_Foley_Live.jpg', 'Canada', 901, 'Sue Foley er en kanadiskfødt bluesgitarist, vokalist og låtskriver som har vært en sentral kvinnelig stemme i moderne blues siden slutten av 1980-tallet.', 'Sue Foley is a Canadian-born blues guitarist, vocalist and songwriter who has been a leading female voice in modern blues since the late 1980s.', 'Sue Foley är en kanadensiskfödd bluesgitarrist, vokalist och låtskrivare som varit en ledande kvinnlig röst inom modern blues sedan slutet av 1980-talet.', 'Sue Foley ist eine in Kanada geborene Blues-Gitarristin, Sängerin und Songwriterin, die seit Ende der 1980er Jahre eine führende weibliche Stimme im modernen Blues ist.', 'Sue Foley to urodzona w Kanadzie gitarzystka, wokalistka i autorka tekstów bluesowych, która od końca lat 80. jest wiodącym kobiecym głosem współczesnego bluesa.');
INSERT INTO artists (id, slug, name, tag, era, active_years, img, country, sort_order, short_no, short_en, short_sv, short_de, short_pl) VALUES (lower(hex(randomblob(16))), 'colin-james', 'Colin James', 'Modern', '1985–present', '1985–present', 'https://upload.wikimedia.org/wikipedia/commons/8/84/ColinJames_2009.jpg', 'Canada', 902, 'Colin James er en av Canadas mest suksessrike og allsidige blues-rock-artister, med en karriere som spenner over flere tiår og sjangre.', 'Colin James is one of Canada''s most successful and versatile blues-rock artists, with a career spanning decades and genres.', 'Colin James är en av Kanadas mest framgångsrika och mångsidiga blues-rock-artister, med en karriär som sträcker sig över flera årtionden och genrer.', 'Colin James ist einer der erfolgreichsten und vielseitigsten Blues-Rock-Künstler Kanadas, mit einer Karriere über mehrere Jahrzehnte und Genres.', 'Colin James to jeden z najbardziej utytułowanych i wszechstronnych kanadyjskich artystów blues-rockowych, z karierą obejmującą dziesięciolecia i gatunki.');
