-- Original guestbook entries recovered from the pre-D1 mock data (git history), never seeded before
INSERT INTO guestbook_entries (id, name, location, message, created_at) VALUES (lower(hex(randomblob(16))), 'Lars', 'Notodden', 'Heard Muddy on the radio at 14. Never looked back. Thanks for keeping the flame alive.', '2026-04-30 09:00:00');
INSERT INTO guestbook_entries (id, name, location, message, created_at) VALUES (lower(hex(randomblob(16))), 'Marianne', NULL, 'Tok med datteren min på Mandal Blues for første gang i fjor — nå er hun frelst på 13 år. Bluesen lever videre.', '2026-04-18 09:00:00');
INSERT INTO guestbook_entries (id, name, location, message, created_at) VALUES (lower(hex(randomblob(16))), 'Tom', 'Hamburg', 'Found this site by accident, lost an entire afternoon in the artist profiles. Beautifully done.', '2026-04-02 09:00:00');
INSERT INTO guestbook_entries (id, name, location, message, created_at) VALUES (lower(hex(randomblob(16))), 'Anna', 'Bergen', 'Tusen takk for det norske perspektivet — sjelden å se Notodden nevnt i samme setning som Chess Records.', '2026-03-21 09:00:00');
-- 8 in-depth album reviews for /reviews, linked to existing artist profiles
-- (personal/enthusiast voice — see conversation for the rewrite pass)
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'muddy-waters-folk-singer', 'muddy-waters', 'Muddy Waters', 'Folk Singer', 1964, 'Chess Records', 'Delta Blues / Acoustic', 'https://upload.wikimedia.org/wikipedia/en/9/98/Muddywatersfolksinger.jpg', 'Album cover — fair use (Wikipedia)', 'The Night Muddy Put the Amp Down', 'Kvelden Muddy la fra seg forsterkeren', 'Turn off the lights, put on headphones, and let a 49-year-old Muddy Waters remind you the blues never needed a single watt of electricity to break your heart.', 'Slukk lyset, ta på hodetelefonene, og la en 49 år gammel Muddy Waters minne deg på at bluesen aldri trengte en eneste watt strøm for å knuse hjertet ditt.', 'I still remember the first time I actually sat down and listened to this record properly, no phone, no distractions, just the record. There''s a moment about forty seconds into "My Home Is in the Delta" where Muddy''s voice drops almost to a whisper and you realize you''ve been holding your breath. That''s the whole record in one moment — a man who spent twenty years teaching Chicago how to plug in the blues, suddenly choosing to strip it all back down to nothing but wood, wire and breath.

You can hear the room. You can hear Buddy Guy — young, reverent, deliberately staying out of Muddy''s way — breathing space into every phrase instead of filling it. This isn''t a man performing the blues for an audience; it''s a man remembering exactly why he started playing it in the first place, on a porch in Mississippi long before Chess Records or amplifiers or any of it existed.

If you only know electric Muddy — the Telecaster snarl, the Chess horn sections, "Mannish Boy" swaggering out of a jukebox — this record will genuinely surprise you. It''s quieter, but it hits harder. Some nights this is the only blues record I want to hear at all.', 9.5, 9, 8.5, 9, 9.7, 9.3, 'SlowBlues Editorial', 'published', '2026-05-04 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'robert-johnson-king-of-the-delta-blues-singers', 'robert-johnson', 'Robert Johnson', 'King of the Delta Blues Singers', 1961, 'Columbia Records', 'Delta Blues', 'https://upload.wikimedia.org/wikipedia/en/e/e6/KotDBS1.jpg', 'Album cover — fair use (Wikipedia)', 'The Record That Sounds Like a Ghost Story Because It Basically Is One', 'Platen som høres ut som en spøkelseshistorie — fordi den nesten er det', 'Twenty-nine songs, one man, one guitar, and a legend that''s swallowed the actual music whole — until you actually press play, and it swallows you instead.', 'Tjueni sanger, én mann, én gitar, og en legende som har svelget selve musikken hel — helt til du faktisk trykker play, og den svelger deg i stedet.', 'Everyone tells you the crossroads story before they tell you to actually listen to the music, and that''s a shame, because the myth undersells what''s really happening on this record. Forget the devil for a second. Listen to what one pair of hands is doing on "Cross Road Blues" — there''s a bassline, a rhythm and a lead melody happening at the same time, from a single acoustic guitar, and it still sounds like a magic trick nine decades later.

What gets me every time is the voice. It cracks. It jumps registers mid-line like he can''t quite contain what he''s singing about. "Hellhound on My Trail" doesn''t sound like a performance — it sounds like a man who genuinely believes something is chasing him, and by the second verse you believe it too. The hiss and crackle of the original 1930s equipment doesn''t get in the way of that; if anything it makes the whole thing feel more like something you shouldn''t have found.

I''ve played this record for people who claim they don''t like old blues, expecting polite nodding, and watched them go completely silent instead. Clapton, Dylan, Keith Richards — they all say the same thing about hearing this for the first time: it rearranges something in you. It still does.', 9.3, 9.6, 7.5, 9.8, 9.9, 9.4, 'SlowBlues Editorial', 'published', '2026-05-11 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'bb-king-live-at-the-regal', 'bb-king', 'B.B. King', 'Live at the Regal', 1965, 'ABC-Paramount', 'Soul Blues / Live', 'https://upload.wikimedia.org/wikipedia/en/2/2f/BB_King-Live_at_the_Regal_%28album_cover%29.jpg', 'Album cover — fair use (Wikipedia)', 'The Night the Regal Theater Nearly Came Apart', 'Kvelden Regal Theater nesten falt fra hverandre', 'Close your eyes during the opening seconds of "Every Day I Have the Blues" and you''re standing in that Chicago crowd on a November night in 1964, and nothing on record has ever topped it.', 'Lukk øynene under de første sekundene av "Every Day I Have the Blues", så står du midt i det publikummet i Chicago en novemberkveld i 1964 — og ingenting på plate har noen gang toppet det.', 'You hear the crowd before you hear a single note of guitar, and that''s not an accident — it''s the whole point. This is a room that has seen B.B. King a dozen times before and still can''t contain itself the second the band kicks in. That kind of reaction can''t be faked or overdubbed. It''s the sound of an audience that already loves every song that''s about to happen.

What kills me is how much King is talking to the crowd through Lucille, mid-solo, like he''s narrating his own performance because he genuinely can''t help himself — "Sweet Little Angel" turns into a call-and-response between his voice, his guitar, and eight hundred people who are all in on it together. By "It''s My Own Fault" you''re not listening to a concert anymore, you''re inside one.

I''ve heard people say recorded blues can never capture what the music is actually for — that you had to be there. This is the one record that makes a liar out of that argument. Rolling Stone ranks it among the greatest albums ever made in any genre and honestly, on the right night, with the volume up, it''s hard to disagree.', 9.7, 9.5, 8.8, 8.9, 9.9, 9.4, 'SlowBlues Editorial', 'published', '2026-05-18 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'howlin-wolf-moanin-in-the-moonlight', 'howlin-wolf', 'Howlin'' Wolf', 'Moanin'' in the Moonlight', 1959, 'Chess Records', 'Chicago Blues', 'https://upload.wikimedia.org/wikipedia/en/4/42/Howlin%27_Wolf_Moanin%27_in_the_Moonlight.jpg', 'Album cover — fair use (Wikipedia)', 'The Sound That Still Makes the Hair on Your Arms Stand Up', 'Lyden som fortsatt får hårene på armen til å reise seg', 'Six foot three, close to 300 pounds, a voice like gravel being shovelled — nearly seventy years on, Howlin'' Wolf''s debut still sounds less like music and more like a warning.', '195 centimeter, nesten 140 kilo, en stemme som grus som skuffes — nesten sytti år senere høres Howlin'' Wolfs debut fortsatt mindre ut som musikk og mer som en advarsel.', 'There''s a specific kind of quiet you go when "Smokestack Lightnin''" starts — that one-chord vamp just circling and circling while Hubert Sumlin''s guitar does something that doesn''t resolve, doesn''t sit still, doesn''t behave. It''s genuinely unsettling in a way I don''t think any other blues record from this era manages. Wolf doesn''t sing the blues so much as he seems barely restrained by it.

Compare him to Muddy Waters — suave, controlled, in command of the room — and Wolf is the opposite on every axis. "Moanin'' at Midnight" sounds like something escaping rather than something performed. I''ve put this record on for friends who think they know what Chicago blues sounds like and watched their whole face change halfway through the first track.

Cream, Zeppelin, the Doors, the Stones — they all went straight to this well and covered these songs, and none of them, in my opinion, ever quite captured what makes the originals so physically unnerving. This isn''t background music. This is a record that requires you to actually sit with it, and I still can''t fully explain why I love returning to something that scares me a little every time.', 9.8, 9.2, 7.8, 9, 9.6, 9.1, 'SlowBlues Editorial', 'published', '2026-06-01 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'albert-king-born-under-a-bad-sign', 'albert-king', 'Albert King', 'Born Under a Bad Sign', 1967, 'Stax Records', 'Texas Blues / Soul Blues', 'https://upload.wikimedia.org/wikipedia/en/3/32/BornUnderABadSign.jpg', 'Album cover — fair use (Wikipedia)', 'The Bend That Changed How an Entire Generation Held a Guitar', 'Bøyningen som forandret måten en hel generasjon holdt gitaren på', 'One upside-down Flying V, one impossibly patient man, and a single string bend so massive it basically wrote the next fifty years of blues-rock guitar by itself.', 'Én opp-ned Flying V, én utrolig tålmodig mann, og én strengbøyning så enorm at den nærmest skrev de neste femti årene med blues-rock-gitar helt alene.', 'The first time you actually see footage of Albert King playing — left-handed, holding a right-handed Flying V flipped over, strings tuned down into something nobody''s ever fully agreed on — it looks almost impossible. Then you hear "Born Under a Bad Sign" and you understand: he wasn''t fighting the guitar, he''d just decided the instrument had to bend to him instead of the other way around.

What gets me about this record is the patience. Booker T. & the M.G.''s and the Memphis Horns are locked into these tight, economical Stax grooves underneath him, and King just refuses to hurry. He''ll hold one note, bent almost past where you think a string should physically go, longer than feels comfortable — and that discomfort is the whole point. Clapton, Hendrix, SRV all chased that exact feeling their entire careers and never quite got there.

"Crosscut Saw" still makes me want to pull the car over. This isn''t a record you put on in the background — it''s a record that reaches out of the speakers and grabs you by the collar, one impossibly held note at a time.', 9.2, 9.7, 9, 9.3, 9.1, 9.3, 'SlowBlues Editorial', 'published', '2026-06-08 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'freddie-king-freddy-king-sings', 'freddie-king', 'Freddie King', 'Freddy King Sings', 1961, 'King Records', 'Texas Blues / Chicago Blues', 'https://upload.wikimedia.org/wikipedia/en/b/bd/Freddy_King_Sings_album_cover.jpg', 'Album cover — fair use (Wikipedia)', 'The Singer Everyone Forgets Because the Guitarist Was Too Good', 'Vokalisten alle glemmer fordi gitaristen var for god', 'History remembers Freddie King for his guitar and quietly forgot he could absolutely tear your heart out with just his voice — this record is the proof they left behind.', 'Historien husker Freddie King for gitaren og glemte stille at han kunne rive hjertet rett ut av deg med bare stemmen — denne platen er beviset de etterlot.', 'Everyone talks about Freddie King''s guitar first — fair enough, it''s extraordinary — but this record is where I fell for his voice instead, and I don''t think enough people give it the credit it deserves. "Have You Ever Loved a Woman" is genuinely one of the most devastating vocal performances in blues, full stop. Clapton knew it too — that''s exactly why Derek and the Dominos covered it, note for aching note.

What I love about this album is how unshowy it is. King grew up absorbing T-Bone Walker''s Texas precision on one side and Chicago''s amplified grit on the other, and here you can hear both traditions arguing it out inside one guy, in real time. "I''m Tore Down" shuffles along with this rhythmic snap that just refuses to let you sit still, and then two songs later he''s wrecking you emotionally with a slow blues that barely raises its voice.

This wasn''t cut to be a landmark. It was a working guitarist and singer cutting sides for a regional label, with zero idea that blues-rock players would still be studying every phrase sixty years on. That''s exactly why it still feels so alive — nobody was performing for history, they were just playing.', 9, 9.4, 8.3, 8.7, 8.8, 8.8, 'SlowBlues Editorial', 'published', '2026-06-15 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'buddy-guy-damn-right-ive-got-the-blues', 'buddy-guy', 'Buddy Guy', 'Damn Right, I''ve Got the Blues', 1991, 'Silvertone Records', 'Chicago Blues / Blues Rock', 'https://upload.wikimedia.org/wikipedia/en/d/d4/BuddyGuy-DamnRight-cover.jpeg', 'Album cover — fair use (Wikipedia)', 'Thirty Years Late and Somehow Perfectly on Time', 'Tretti år for sent og på en eller annen måte helt presist i tide', 'After decades of being told he was ''too much'' for the studio, Buddy Guy finally got a record built entirely around the fact that too much was always the entire point.', 'Etter tiår med å bli fortalt at han var ''for mye'' for studioet, fikk Buddy Guy endelig en plate bygget helt rundt det faktum at ''for mye'' alltid var hele poenget.', 'There''s something almost unbearably satisfying about knowing the backstory before you hit play on the title track. Leonard Chess reportedly thought Buddy Guy''s wild, theatrical style was too much for a Chess Records session back in the sixties — too loud, too unpredictable, too everything. Thirty years later, here''s an entire album built to give him exactly the room Chess never did, and you can hear him take every inch of it.

Eric Clapton shows up on "Early in the Morning" and it plays less like a guest verse and more like a student publicly thanking a teacher he never got to properly repay — Hendrix, Clapton, Vaughan all built entire careers out of what Buddy Guy was doing in Chicago clubs decades earlier, largely unheard outside them. Hearing him finally get his own spotlight, with the people he inspired standing right beside him, hits different every single time.

Is it slicker than his sixties work? Sure. But the playing itself hasn''t lost an ounce of danger — if anything, thirty years of being overlooked put an extra edge on it. This is the record that reintroduced an entire generation to one of the last living bridges between Chicago blues and the rock guitar it created, and it still sounds like a man with something to prove.', 9.1, 9.5, 9, 8.8, 9, 9.1, 'SlowBlues Editorial', 'published', '2026-06-22 10:00:00');
INSERT INTO blues_reviews (id, slug, artist_slug, artist_name, album_title, release_year, label, blues_style, cover_image, cover_credit, title_en, title_no, verdict_en, verdict_no, body_en, score_vocals, score_instrumentation, score_production, score_songwriting, score_atmosphere, total_score, reviewer, status, published_at) VALUES (lower(hex(randomblob(16))), 'stevie-ray-vaughan-texas-flood', 'stevie-ray-vaughan', 'Stevie Ray Vaughan', 'Texas Flood', 1983, 'Epic Records', 'Texas Blues', 'https://upload.wikimedia.org/wikipedia/en/5/5e/StevieRayVaughanTexasFlood.jpg', 'Album cover — fair use (Wikipedia)', 'A 28-Year-Old with Nothing to Lose and Everything to Prove', 'En 28-åring med ingenting å tape og alt å bevise', 'Cut essentially live over one weekend for pocket change, Texas Flood sounds exactly like what it was — a guitarist with everything on the line, refusing to hold anything back.', 'Spilt inn nærmest live på én helg for småpenger — Texas Flood høres ut akkurat som det det var: en gitarist med alt på spill, som nekter å holde noe tilbake.', '"Pride and Joy" is the song everyone knows, and fair enough, it''s an instant shuffle so effortless it became a standard within months. But I always end up going back to the title track for the real gut-punch. It''s a slow, cavernous 12-bar blues, and you can hear Vaughan physically attacking the strings — an almost violent intensity that somehow, impossibly, never loses control of a single note.

Recorded essentially live off an unbilled, jaw-dropping set at Montreux in ''82 that nobody expected, for a few thousand dollars, in a room with almost no overdubs — this is a guitarist with everything to prove and nothing to fall back on if it didn''t land. That hunger is all over the record. Then "Lenny," written for his wife, shows up and suddenly he''s tender, patient, completely different — proof this wasn''t a one-note guy even at 28.

Vaughan got more polished later, more famous, arguably more accomplished. But he never sounded hungrier than he does here, and that hunger is exactly why I keep coming back to this one over the rest of his catalogue. This is the sound of blues guitar refusing to become a museum piece.', 8.8, 9.8, 9, 8.9, 9.2, 9.1, 'SlowBlues Editorial', 'published', '2026-06-29 10:00:00');
